-- Colombia: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'co-large-taxpayers-2018', id, '2018-09-01', 1, 'https://www.dian.gov.co/impuestos/factura-electronica/documentacion/Paginas/normativa.aspx', 1, '[{"label": "DIAN e-invoicing portal", "url": "https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/"}]', NULL, 'b2b' FROM countries WHERE code = 'CO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-large-taxpayers-2018', 'en', 'Resolucion 000010 de 2018 (DIAN)', 'DIAN Resolution 000010/2018 (6 February 2018) ordered every taxpayer classified as a ''gran contribuyente'' (large taxpayer) onto the DIAN pre-validation clearance e-invoicing system from 1 September 2018 -- Colombia''s first mandatory wave, building on optional pilots dating back to 1995''s legal recognition of e-invoices and Decree 2242/2015''s framework.', '["Obtain an accredited digital certificate and DIAN-compliant invoicing software able to generate UBL-based XML.", "Transmit every invoice to DIAN for real-time pre-validation before delivering it to the buyer.", "Retain validated invoices and their DIAN acceptance record for at least 5 years."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'co-universal-2020', id, '2020-11-01', 0, 'https://www.dian.gov.co/normatividad/Normatividad/Resoluci%C3%B3n%20000042%20de%2005-05-2020.pdf', 1, '[{"label": "DIAN e-invoicing portal", "url": "https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/"}]', NULL, 'b2b' FROM countries WHERE code = 'CO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-universal-2020', 'en', 'Resolucion 000042 de 2020 (DIAN)', 'Resolution 000042/2020 (5 May 2020) set a staggered calendar bringing the remaining taxpayer groups onto mandatory e-invoicing through 2020; the final wave (Groups 6, 7 and 8) landed on 1 November 2020, making DIAN''s real-time CUFE clearance model mandatory for essentially every VAT- and national-consumption-tax-responsible business in Colombia -- covering B2B, B2C and B2G sales alike.', '["Onboard certified e-invoicing software before your taxpayer group''s 2020 deadline (final wave: 1 November).", "Cover B2B, B2C, and B2G sales alike under the same CUFE clearance flow.", "Simple Tax Regime (SIMPLE) taxpayers: comply within 2 months of enrollment rather than a fixed group date."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'co-equivalent-documents-2024', id, '2024-11-01', 0, 'https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/normatividad/', 1, '[{"label": "DIAN e-invoicing portal", "url": "https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/"}]', NULL, 'none' FROM countries WHERE code = 'CO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-equivalent-documents-2024', 'en', 'Resolucion 000165 de 2023 + Resolucion 000008 de 2024 (DIAN)', 'Resolution 000165/2023 (1 November 2023) converted Colombia''s paper ''documentos equivalentes'' -- POS receipts, utility bills, passenger transport and airline tickets, gambling and toll receipts -- into fully electronic, DIAN-validated documents. Resolution 000008/2024 extended the original deadlines to give businesses more time; by 1 November 2024 every remaining document category (cinema and entertainment tickets, the last group) had converted, closing out the phase-in.', '["Update POS/billing systems to generate and transmit the new electronic equivalent-document formats to DIAN.", "Meet your document category''s 2024 deadline (POS tickets from May 2024 through cinema/entertainment tickets by 1 November 2024).", "Use electronic POS tickets as valid cost/tax support regardless of transaction amount, per the expanded rules."]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'co-b2c-refinements-2025', id, '2025-03-31', 0, 'https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/normatividad/', 1, '[{"label": "DIAN e-invoicing portal", "url": "https://micrositios.dian.gov.co/sistema-de-facturacion-electronica/"}]', NULL, 'none' FROM countries WHERE code = 'CO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-b2c-refinements-2025', 'en', 'Resolucion 000202 de 2025 (DIAN)', 'Resolution 000202/2025 (31 March 2025) refined the existing universal mandate rather than expanding who is covered: retailers may now capture only a buyer''s name, ID type/number and email for point-of-sale invoices (with DIAN auto-fill from its own registry for parties already on file), and utility providers with genuine connectivity problems in rural areas gained a 48-hour window to transmit invoices after issuance instead of DIAN''s usual near-real-time validation.', '["Switch point-of-sale invoicing to the streamlined buyer-data flow (name, ID type/number, email) with DIAN auto-fill.", "Qualifying rural/connectivity-constrained utility providers: use the new 48-hour transmission window instead of near-real-time validation."]');
